{"content": """"
nir_lib.py — 近红外光谱定量分析核心库（教学用，全部手写可读）

包含：
  1) 预处理：SG 平滑/求导、SNV、MSC、去趋势
  2) 样本集划分：SPXY（Galvao 2005）、Kennard-Stone、随机
  3) 建模：PLS（含交叉验证选主成分数）
  4) 变量筛选：CARS（Li 2009）
  5) 评价指标：R2、RMSE、RPD、RER、bias

约定：
  X: (n_samples, n_wavelengths)  float
  y: (n_samples,)                float
  所有需要"学习"的预处理（MSC）必须只用校正集 fit，再 transform 预测集，避免信息泄漏。
"""
from __future__ import annotations

import numpy as np
from scipy.signal import savgol_filter
from scipy.spatial.distance import pdist, squareform
from sklearn.cross_decomposition import PLSRegression


# ============================================================
# 1. 预处理
# ============================================================
def sg(X, window=11, poly=3, deriv=0, delta=1.0):
    """Savitzky-Golay 平滑(deriv=0)或求导(deriv=1/2)。

    window: 窗口点数，必须为奇数且 > poly
    poly  : 多项式阶数，通常 2 或 3
    deriv : 0=只平滑, 1=一阶导, 2=二阶导
    delta : 波长间隔(nm)，求导后量纲要除以它
    """
    if window % 2 == 0:
        window += 1
    window = min(window, X.shape[1] if X.shape[1] % 2 == 1 else X.shape[1] - 1)
    if window <= poly:
        raise ValueError("window 必须大于 poly")
    return savgol_filter(X, window_length=window, polyorder=poly,
                         deriv=deriv, delta=delta, axis=1, mode="interp")


def snv(X):
    """标准正态变量变换：每条光谱减自身均值、除自身标准差。

    消的是"同一条光谱内部"的乘性散射与基线平移，逐样本独立，不需要 fit。
    """
    mu = X.mean(axis=1, keepdims=True)
    sd = X.std(axis=1, ddof=1, keepdims=True)
    sd[sd == 0] = 1.0
    return (X - mu) / sd


class MSC:
    """多元散射校正。参考光谱 = 校正集平均光谱（必须只用校正集算）。

    对每条光谱 x 做一元回归 x = a + b * x_ref，然后 (x - a) / b。
    """

    def __init__(self):
        self.ref_ = None

    def fit(self, X):
        self.ref_ = X.mean(axis=0, keepdims=True)
        return self

    def transform(self, X):
        if self.ref_ is None:
            raise RuntimeError("先 fit")
        xr = self.ref_.ravel()
        out = np.empty_like(X, dtype=float)
        xr_c = xr - xr.mean()
        denom = (xr_c ** 2).sum()
        for i in range(X.shape[0]):
            xi = X[i]
            b = ((xi - xi.mean()) * xr_c).sum() / denom
            a = xi.mean() - b * xr.mean()
            out[i] = (xi - a) / b
        return out

    def fit_transform(self, X):
        return self.fit(X).transform(X)


def detrend(X, order=1):
    """逐条光谱去趋势（多项式拟合基线后减掉）。"""
    n, p = X.shape
    t = np.linspace(-1, 1, p)
    out = np.empty_like(X, dtype=float)
    for i in range(n):
        c = np.polyfit(t, X[i], order)
        out[i] = X[i] - np.polyval(c, t)
    return out


class Preprocessor:
    """把若干步骤串起来。步骤名 -> 可调用对象。

    可用: 'sg', 'sg1', 'sg2', 'snv', 'msc', 'detrend', 'none'
    组合写法: "snv+sg1" 表示先 SNV 再一阶导
    """

    def __init__(self, spec: str, window=11, poly=3, delta=2.0):
        self.spec = spec
        self.window = window
        self.poly = poly
        self.delta = delta
        self.msc_ = None

    def _steps(self):
        if self.spec in ("none", "", None):
            return []
        return self.spec.split("+")

    def fit(self, X):
        for s in self._steps():
            if s == "msc":
                self.msc_ = MSC().fit(X)
                X = self.msc_.transform(X)
            else:
                X = self._apply(s, X)
        return self

    def _apply(self, s, X):
        if s == "sg":
            return sg(X, self.window, self.poly, 0, self.delta)
        if s == "sg1":
            return sg(X, self.window, self.poly, 1, self.delta)
        if s == "sg2":
            return sg(X, self.window, self.poly, 2, self.delta)
        if s == "snv":
            return snv(X)
        if s == "detrend":
            return detrend(X)
        raise ValueError(f"未知预处理步骤 {s}")

    def transform(self, X):
        for s in self._steps():
            if s == "msc":
                if self.msc_ is None:
                    raise RuntimeError("MSC 未 fit")
                X = self.msc_.transform(X)
            else:
                X = self._apply(s, X)
        return X

    def fit_transform(self, X):
        return self.fit(X).transform(X)


# ============================================================
# 2. 样本集划分
# ============================================================
def _dist_matrix(X, y, alpha=0.5):
    """SPXY 联合距离矩阵。alpha=1 退化为 KS。"""
    dx = squareform(pdist(X, metric="euclidean"))
    dx = dx / dx.max()
    if alpha >= 1.0:
        return dx
    yy = np.asarray(y, dtype=float)
    if yy.ndim == 1:
        yy = yy[:, None]
    dy = squareform(pdist(yy, metric="euclidean"))
    if dy.max() > 0:
        dy = dy / dy.max()
    return alpha * dx + (1 - alpha) * dy


def spxy(X, y, n_train, alpha=0.5):
    """SPXY 划分，返回 (train_idx, test_idx)。

    算法（与 KS 同构，只是距离换成 X-Y 联合距离）：
      1. 选距离最远的一对样本进校正集
      2. 反复：对每个未选样本，算它到已选集合的最小距离，取最大者进校正集
      3. 选够 n_train 个为止，其余为预测集
    """
    n = X.shape[0]
    D = _dist_matrix(X, y, alpha)
    selected = []
    i, j = np.unravel_index(np.argmax(D), D.shape)
    selected += [int(i), int(j)]
    min_d = np.minimum(D[i], D[j]).astype(float)
    min_d[selected] = -np.inf
    while len(selected) < n_train:
        k = int(np.argmax(min_d))
        selected.append(k)
        min_d = np.minimum(min_d, D[k])
        min_d[selected] = -np.inf
    mask = np.zeros(n, bool)
    mask[selected] = True
    return np.array(selected), np.where(~mask)[0]


def kennard_stone(X, n_train):
    return spxy(X, np.zeros(X.shape[0]), n_train, alpha=1.0)


def random_split(n, n_train, seed=0):
    idx = np.random.default_rng(seed).permutation(n)
    return np.sort(idx[:n_train]), np.sort(idx[n_train:])


# ============================================================
# 3. PLS 与交叉验证
