{"content": "%% matlab_check.m — MATLAB 独立实现，与 Python 结果对账
% 一、按 Python 导出的划分与折号，验证两边的 SG/SNV/PLS 实现是否一致
% 二、MATLAB 自己做一遍 SPXY，验证算法实现是否正确

clear; clc;

base = 'C:\Users\UserX\bq_nir';
S = load(fullfile(base, 'data', 'processed', 'matlab_in.mat'));
X = S.X;  y = S.y(:);  delta = S.delta;
tr = S.train_idx(:);  te = S.test_idx(:);  fold_id = S.fold_id(:);
fprintf('数据 %d x %d, delta=%.1f nm, 校正 %d, 预测 %d\n', ...
        size(X,1), size(X,2), delta, numel(tr), numel(te));

%% ---------- 1) 预处理：SNV ----------
mu = mean(X, 2);
sd = std(X, 0, 2);
Xsnv = (X - mu) ./ sd;

%% ---------- 2) SG 一阶导（窗口 11, 多项式 2 阶） ----------
% sgolayfilt 只做平滑。一阶导用 Python 完全相同的定义：
% savgol_filter(deriv=1, delta=delta)，即用 SG 拟合多项式的解析导数
% 在中心点取值。手工实现：对每个点做局部多项式拟合，取一次项系数 / delta。
order = 2;  win = 11;  half = (win-1)/2;
% SG 求导核：对相对位置 t=-half..half 拟合，取一阶系数
t = (-half:half)';
V = zeros(win, order+1);
for k = 0:order
    V(:, k+1) = t.^k;
end
% 一阶导数（系数按 1/1! 缩放）对应的权重：
% p(t) = sum c_k t^k, p'(0) = c_1；而 c = pinv(V) * f
% 故 p'(0) = pinv(V)(2,:) * f
c1 = pinv(V);  c1 = c1(2, :);
% 二阶导数 p''(0) = 2*c_2
c2 = pinv(V);  c2 = 2 * c2(3, :);

Xsg1 = conv2(Xsnv, fliplr(c1), 'same') / delta;
Xsg2 = conv2(Xsnv, fliplr(c2), 'same') / delta^2;

% 边界修正：conv2 'same' 在两端用零填充，误差大；改为对边界点逐个做局部拟合
for i = 1:size(Xsnv,1)
    for j = 1:half
        lo = 1; hi = win;
        if j <= half
            lo = 1; hi = win;
        end
        seg = Xsnv(i, lo:hi);
        Xsg1(i, j) = (pinv(V) * seg')' * (0:order)' .* (0:order)' ;
    end
end
% 上面循环写法易错，改用更稳妥的方式重做边界
Xsg1 = sgderiv(Xsnv, order, win, 1) / delta;
Xsg2 = sgderiv(Xsnv, order, win, 2) / delta^2;

%% ---------- 3) 用 Python 的划分与折号，复算 CV 曲线 ----------
Xp = Xsg1;
nTr = numel(tr);
maxComp = 15;
rmscv = nan(maxComp, 1);
for k = 1:maxComp
    pred = nan(nTr, 1);
    for f = 1:10
        va = find(fold_id == f);
        ca = setdiff(1:nTr, va);
        beta = plsregress_simple(Xp(tr(ca), :), y(tr(ca)), k);
        pred(va) = [ones(numel(va),1), Xp(tr(va), :)] * beta;
    end
    rmscv(k) = sqrt(mean((y(tr) - pred).^2));
end
[bestRMSE, bestK] = min(rmscv);
fprintf('\n[用 Python 的划分/折号]\n');
fprintf('  best k=%d  RMSECV=%.5f\n', bestK, bestRMSE);

beta = plsregress_simple(Xp(tr,:), y(tr), bestK);
predC = [ones(numel(tr),1), Xp(tr,:)] * beta;
predT = [ones(numel(te),1), Xp(te,:)] * beta;
rmseC = sqrt(mean((y(tr)-predC).^2));
rmseT = sqrt(mean((y(te)-predT).^2));
R2c = 1 - sum((y(tr)-predC).^2)/sum((y(tr)-mean(y(tr))).^2);
R2t = 1 - sum((y(te)-predT).^2)/sum((y(te)-mean(y(te))).^2);
fprintf('  RMSEC=%.5f  R2c=%.5f\n', rmseC, R2c);
fprintf('  RMSEP=%.5f  R2p=%.5f  RPD=%.4f\n', rmseT, R2t, std(y(te))/rmseT);

%% ---------- 4) MATLAB 独立做 SPXY + SNV + SG1 ----------
Dx = pdist2(X, X);  Dx = Dx / max(Dx(:));
Dy = pdist2(y, y);  Dy = Dy / max(Dy(:));
D = 0.5*Dx + 0.5*Dy;
n = size(X,1);
sel = zeros(1, nTr);
[~, idx] = max(D(:));
[sel(1), sel(2)] = ind2sub([n n], idx);
minD = min(D(sel(1), :), D(sel(2), :));
minD(sel(1:2)) = -inf;
for k = 3:nTr
    [~, j] = max(minD);
    sel(k) = j;
    minD = min(minD, D(j, :));
    minD(sel(1:k)) = -inf;
end
tr2 = sort(sel(:));
te2 = setdiff((1:n)', tr2);
fprintf('\n[MATLAB 独立 SPXY]\n');
fprintf('  与 Python 划分一致: %d\n', isequal(sort(tr2), sort(tr)));

% 用同一预处理与 PLS 复算
Xp2 = Xsg1;
rmscv2 = nan(maxComp,1);
perm2 = randperm(nTr);      % 折号与 Python 不同，看结果是否落在同一量级
fid2 = zeros(nTr,1);
for f = 1:10
    fid2(perm2(f:10:end)) = f;
end
for k = 1:maxComp
    pred = nan(nTr,1);
    for f = 1:10
        va = find(fid2 == f);
        ca = setdiff(1:nTr, va);
        beta = plsregress_simple(Xp2(tr2(ca),:), y(tr2(ca)), k);
        pred(va) = [ones(numel(va),1), Xp2(tr2(va),:)] * beta;
    end
    rmscv2(k) = sqrt(mean((y(tr2)-pred).^2));
end
[best2, k2] = min(rmscv2);
beta = plsregress_simple(Xp2(tr2,:), y(tr2), k2);
pC = [ones(numel(tr2),1), Xp2(tr2,:)] * beta;
pT = [ones(numel(te2),1), Xp2(te2,:)] * beta;
fprintf('  best k=%d  RMSECV=%.5f  RMSEC=%.5f  RMSEP=%.5f  R2p=%.5f\n', ...
        k2, best2, sqrt(mean((y(tr2)-pC).^2)), sqrt(mean((y(te2)-pT).^2)), ...
        1 - sum((y(te2)-pT).^2)/sum((y(te2)-mean(y(te2))).^2));

%% ---------- 5) 与 Python 的 SG1 结果逐点比较 ----------
if isfield(S, 'Xsg1_py')
    d = abs(Xsg1(:) - S.Xsg1_py(:));
    fprintf('\n[与 Python 预处理结果比对]\n');
    fprintf('  max|diff|=%.3e  mean|diff|=%.3e  (信号量级 %.3f)\n', ...
            max(d), mean(d), mean(abs(S.Xsg1_py(:))));
