%% ================= 局部函数 =================
function Xd = sgderiv(X, order, win, deriv)
    % 与 scipy.signal.savgol_filter 等价的 SG 求导（含两端局部拟合）
    [n, p] = size(X);
    half = (win-1)/2;
    t = (-half:half)';
    V = zeros(win, order+1);
    for k = 0:order
        V(:, k+1) = t.^k;
    end
    P = pinv(V);
    % 中心点核：p^(deriv)(0) = deriv! * c_deriv
    kern = factorial(deriv) * P(deriv+1, :);
    Xd = conv2(X, fliplr(kern), 'same');
    % 两端：用单边局部拟合
    for i = 1:n
        for j = 1:half
            seg = X(i, 1:win);          % 左端
            tt = (-half:half)' + (half - j + 1);
            Vj = zeros(win, order+1);
            for k = 0:order
                Vj(:, k+1) = tt.^k;
            end
            Xd(i, j) = factorial(deriv) * (pinv(Vj) * seg')(deriv+1);
            seg = X(i, p-win+1:p);      % 右端
            tt = (-half:half)' - (j);
            Vj = zeros(win, order+1);
            for k = 0:order
                Vj(:, k+1) = tt.^k;
            end
            Xd(i, p-j+1) = factorial(deriv) * (pinv(Vj) * seg')(deriv+1);
        end
    end
end

function beta = plsregress_simple(X, y, k)
    % 用 MATLAB 自带 plsregress，返回 [截距; 系数]
    [~, ~, ~, ~, beta] = plsregress(X, y, k);
end
