{"content": "%% matlab_check.m — MATLAB 独立实现，与 Python 结果对账
%
% 两部分：
%   A. 用 Python 导出的划分与折号，逐步复算 SNV → SG1 → PLS，
%      与 Python 的中间结果逐元素比对，证明两种工具实现的是同一算法。
%   B. MATLAB 完全独立地做一遍 SPXY，验证划分算法本身的实现正确性。
%
% 用法：matlab -batch "run('C:\Users\UserX\bq_nir\matlab\matlab_check.m')"

clear; clc;

base = 'C:\Users\UserX\bq_nir';
S = load(fullfile(base, 'data', 'processed', 'matlab_in.mat'));
X = S.X;  y = S.y(:);  delta = S.delta;
tr = S.train_idx(:);  te = S.test_idx(:);  fold_id = S.fold_id(:);
fprintf('数据 %d x %d, delta=%.1f nm, 校正 %d, 预测 %d\n', ...
        size(X,1), size(X,2), delta, numel(tr), numel(te));

%% ===== A1. SNV =====
mu = mean(X, 2);
sd = std(X, 0, 2);
Xsnv = (X - mu) ./ sd;

d = abs(Xsnv(:) - S.Xsnv_py(:));
fprintf('\n[A1] SNV 与 Python 比对: max|diff|=%.3e, mean|diff|=%.3e\n', ...
        max(d), mean(d));

%% ===== A2. SG 一阶导（窗口 11，2 阶多项式，delta 已计入） =====
Xsg1 = sgderiv(Xsnv, 2, 11, 1) / delta;

d = abs(Xsg1(:) - S.Xsg1_py(:));
fprintf('[A2] SG1 与 Python 比对: max|diff|=%.3e, mean|diff|=%.3e\n', ...
        max(d), mean(d));

%% ===== A3. PLS CV 曲线（用 Python 的折号） =====
Xp = Xsg1;
nTr = numel(tr);
maxComp = 15;
rmscv = nan(maxComp, 1);
for k = 1:maxComp
    pred = nan(nTr, 1);
    for f = 1:10
        va = find(fold_id == f);
        ca = setdiff(1:nTr, va);
        beta = pls_beta(Xp(tr(ca), :), y(tr(ca)), k);
        pred(va) = [ones(numel(va),1), Xp(tr(va), :)] * beta;
    end
    rmscv(k) = sqrt(mean((y(tr) - pred).^2));
end
[bestRMSE, bestK] = min(rmscv);

fprintf('\n[A3] 用 Python 的划分与折号：\n');
fprintf('     best k=%d  RMSECV=%.6f   (Python 侧 : k=%d, RMSECV=%.6f)\n', ...
        bestK, bestRMSE, S.py_bestK, S.py_rmscv);

%% ===== A4. 最终模型与预测 =====
beta = pls_beta(Xp(tr,:), y(tr), bestK);
predC = [ones(numel(tr),1), Xp(tr,:)] * beta;
predT = [ones(numel(te),1), Xp(te,:)] * beta;
rmseC = sqrt(mean((y(tr)-predC).^2));
rmseT = sqrt(mean((y(te)-predT).^2));
R2c = 1 - sum((y(tr)-predC).^2)/sum((y(tr)-mean(y(tr))).^2);
R2t = 1 - sum((y(te)-predT).^2)/sum((y(te)-mean(y(te))).^2);

fprintf('[A4] RMSEC=%.6f  R2c=%.6f\n', rmseC, R2c);
fprintf('     RMSEP=%.6f  R2p=%.6f  RPD=%.4f\n', rmseT, R2t, std(y(te))/rmseT);
fprintf('     Python 侧: RMSEC=%.6f  R2c=%.6f  RMSEP=%.6f  R2p=%.6f  RPD=%.4f\n', ...
        S.py_rmseC, S.py_R2c, S.py_rmseP, S.py_R2p, S.py_RPD);

%% ===== B. MATLAB 独立 SPXY =====
Dx = pdist2(X, X);  Dx = Dx / max(Dx(:));
Dy = pdist2(y, y);  Dy = Dy / max(Dy(:));
D = 0.5*Dx + 0.5*Dy;

n = size(X,1);
sel = zeros(1, nTr);
[~, idx] = max(D(:));
[sel(1), sel(2)] = ind2sub([n n], idx);
minD = min(D(sel(1), :), D(sel(2), :));
minD(sel(1:2)) = -inf;
for k = 3:nTr
    [~, j] = max(minD);
    sel(k) = j;
    minD = min(minD, D(j, :));
    minD(sel(1:k)) = -inf;
end
tr2 = sort(sel(:));
te2 = setdiff((1:n)', tr2);

fprintf('\n[B] MATLAB 独立 SPXY：\n');
fprintf('    与 Python 导出的校正集完全一致: %d\n', isequal(tr2, sort(tr)));
fprintf('    校正集参考值 mean=%.4f sd=%.4f\n', mean(y(tr2)), std(y(tr2)));

%% ================= 局部函数 =================
function Xd = sgderiv(X, order, win, deriv)
    % 与 scipy.signal.savgol_filter(deriv=d) 等价的 SG 求导。
    % 内部点用卷积核；两端用单边局部多项式拟合（与 scipy 的 interp 模式一致）。
    [n, p] = size(X);
    half = (win-1)/2;
    t = (-half:half)';

    V = zeros(win, order+1);
    for k = 0:order
        V(:, k+1) = t.^k;
    end
    P = pinv(V);
    kern = factorial(deriv) * P(deriv+1, :);      % 中心点求导核

    Xd = conv2(X, fliplr(kern), 'same');

    % 左端：拟合窗口 [1, win]，但要取第 j 个位置处的导数
    for j = 1:half
        Xd(:, j) = local_deriv(X(:, 1:win), t, order, deriv, j, half);
    end
    % 右端
    for j = 1:half
        Xd(:, p-j+1) = local_deriv(X(:, p-win+1:p), t, order, deriv, j, half);
    end
end

function out = local_deriv(seg, t, order, deriv, j, half)
    % seg: n x win；求窗口内第 (half - j + 1) 个采样点处（相对坐标）的导数
    shift = half - j + 1;
    tt = t - shift;
    Vj = zeros(numel(t), order+1);
    for k = 0:order
        Vj(:, k+1) = tt.^k;
    end
    c = (pinv(Vj) * seg')';                       % n x (order+1)
    out = factorial(deriv) * c(:, deriv+1);
end

function beta = pls_beta(X, y, k)
    [~, ~, ~, ~, beta] = plsregress(X, y, k);
end
